python3 - <<'EOF'
p='src/assets/style.css'
s=open(p).read()
marker="/*\n * Compact conversation list"
block='''/*
 * Drawer rows (DESIGN.md "Drawer Row"): the one anatomy shared by Activity,
 * Drafts, Reminders and Cached Trash. A 36px row on 12px type, separated by
 * rhythm alone (no borders). The text sits on the drawer's 24px content edge;
 * the Focus Stone fill reaches 6px past it, with a 4px radius. The primary
 * action is one real button (`.drawer-row-main`, marked `data-drawer-row` for
 * the shared roving keyboard model); quiet ghost buttons and one status word
 * sit in the trailing slot. Focus uses the standard 2px ring, never a lavender
 * bar: the row is not "the current row" of the list.
 */
.drawer-rows {
  list-style: none;
  margin: 0;
  padding: 0;
}

.drawer-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 36px;
  margin-inline: -6px;
  padding-inline: 6px;
  border-radius: 4px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  color: var(--text-primary);
}

.drawer-row:hover,
.drawer-row:has(:focus-visible) {
  background: var(--focus-fill);
}

.drawer-row-main {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  gap: 12px;
  min-width: 0;
  min-height: 36px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}

.drawer-row-trailing {
  display: flex;
  flex: none;
  align-items: center;
  gap: 6px;
}

.row-subject,
.row-sender {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-subject {
  flex: 1 1 auto;
}

.row-sender {
  flex: 0 1 9em;
  font-weight: var(--weight-strong);
}

.row-strong,
.activity-action {
  font-weight: var(--weight-strong);
}

.activity-action,
.row-date,
.row-flag {
  flex: none;
  white-space: nowrap;
}

.row-date,
.row-flag,
.row-empty {
  color: var(--text-secondary);
}

.row-date {
  font-variant-numeric: tabular-nums;
}

.activity-status {
  flex: none;
  white-space: nowrap;
}

/* Status colour lives on the word alone (Status-Is-Sacred: words, not tints). */
.tone-warn {
  color: var(--warning);
}

.tone-fault {
  color: var(--danger);
}

.activity-status.tone-calm {
  color: var(--text-secondary);
}

/* Lines under a row or a toolbar: Ash notes, Coral alerts, plain lines. */
.drawer-note,
.drawer-alert,
.drawer-line {
  margin: 0 0 6px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  overflow-wrap: anywhere;
}

.drawer-note {
  color: var(--text-secondary);
}

.drawer-alert {
  color: var(--danger);
}

.drawer-section {
  margin: 0 0 12px;
}

.drawer-section-title {
  margin: 0 0 6px;
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
}

.drawer-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 0 6px;
}

.drawer-toolbar > .drawer-note {
  margin: 0;
}

.drawer-row-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 0 0 6px;
}

/* Ghost buttons in a drawer: quiet Ash text, Paper White Title weight for the
   one action, Focus Stone for a choice. Their text lines up with the content
   edge; the 8px padding is only the hit target. */
.drawer-quiet,
.drawer-action,
.drawer-primary,
.drawer-chip {
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  background: transparent;
  font: inherit;
}

.drawer-quiet {
  color: var(--text-secondary);
}

.drawer-action {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.drawer-chip {
  color: var(--text-secondary);
}

.drawer-chip[aria-pressed='true'] {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.drawer-primary {
  background: var(--focus-fill);
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.drawer-quiet:hover:not(:disabled),
.drawer-action:hover:not(:disabled),
.drawer-chip:hover:not(:disabled) {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.drawer-primary:hover:not(:disabled) {
  background: var(--focus-fill);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

/* On a hovered row the fill already equals the button hover fill: add the ring. */
.drawer-row .drawer-quiet:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.drawer-line > .drawer-quiet:first-child,
